    public static final int BOARD_HEIGHT = ROWS * CELL_SIZE;  // 600
    public static final int SIDE_PANEL_WIDTH = 180;
    public static final int WINDOW_WIDTH = BOARD_WIDTH + SIDE_PANEL_WIDTH + 40;  // 520
    public static final int WINDOW_HEIGHT = BOARD_HEIGHT + 80;  // 680

    // ==================== 颜色定义 ====================
    public static final Color BG_COLOR = new Color(0x1a1a2e);
    public static final Color BOARD_BG = new Color(0x16213e);
    public static final Color GRID_COLOR = new Color(0x2a2a4e);
    public static final Color BORDER_COLOR = new Color(0x3a3a5e);
    public static final Color TEXT_COLOR = Color.WHITE;
    public static final Color ACCENT_COLOR = new Color(0x00d9ff);

    // 方块颜色数组 (ARGB)
    public static final Color[] TETROMINO_COLORS = {
        new Color(0xFF00d9ff),  // I型 - 青色
        new Color(0xFFffd700),  // O型 - 金色
        new Color(0xFF9b59b6),  // T型 - 紫色
        new Color(0xFF2ecc71),  // S型 - 绿色
        new Color(0xFFe74c3c),  // Z型 - 红色
        new Color(0xFF3498db),  // J型 - 蓝色
        new Color(0xFFe67e22),  // L型 - 橙色
