    public static final Color BLOCK_HIGHLIGHT = new Color(0x30FFFFFF);

    // ==================== 游戏速度 (毫秒) ====================
    public static final int[] LEVEL_SPEEDS = {
        1000,  // Level 1
        900,   // Level 2
        800,   // Level 3
        700,   // Level 4
        600,   // Level 5
        500,   // Level 6
        400,   // Level 7
        300,   // Level 8
        200,   // Level 9
        100,   // Level 10
    };

    // ==================== 计分规则 ====================
    public static final int[] LINE_SCORES = {0, 100, 300, 500, 800};  // 0-4行消除
    public static final int SOFT_DROP_SCORE = 1;    // 每格1分
    public static final int HARD_DROP_SCORE = 2;    // 每格2分
    public static final int LINES_PER_LEVEL = 10;   // 每10行升级

    // ==================== 方块索引 ====================
    public static final int EMPTY = -1;
    public static final int I = 0, O = 1, T = 2, S = 3, Z = 4, J = 5, L = 6;

    // ==================== 字体 ====================
    public static final Font TITLE_FONT = new Font("Arial", Font.BOLD, 28);
    public static final Font LABEL_FONT = new Font("Arial", Font.BOLD, 14);
    public static final Font VALUE_FONT = new Font("Arial", Font.PLAIN, 16);
    public static final Font CONTROL_FONT = new Font("Consolas", Font.PLAIN, 12);

    private Constants() {}  // 防止实例化
}

