package game;

import util.Constants;

/**
 * 游戏板类，管理10x20的游戏网格
 */
public class Board {
    private int[][] grid;  // grid[row][col], -1=空, 0-6=方块颜色索引

    public Board() {
        grid = new int[Constants.ROWS][Constants.COLS];
        clear();
    }

    /**
     * 清空游戏板
     */
    public void clear() {
        for (int row = 0; row < Constants.ROWS; row++) {
            for (int col = 0; col < Constants.COLS; col++) {
                grid[row][col] = Constants.EMPTY;
            }
        }
    }

    /**
     * 获取指定位置的方块颜色
     * @param row 行
     * @param col 列
     * @return 颜色索引，-1表示空
     */
    public int getCell(int row, int col) {
        if (row < 0 || row >= Constants.ROWS || col < 0 || col >= Constants.COLS) {
            return Constants.EMPTY;
        }
        return grid[row][col];
    }

    /**
     * 设置指定位置的方块颜色
     * @param row 行
     * @param col 列
     * @param colorIndex 颜色索引
     */
    public void setCell(int row, int col, int colorIndex) {
        if (row >= 0 && row < Constants.ROWS && col >= 0 && col < Constants.COLS) {
            grid[row][col] = colorIndex;
        }
    }

    /**
     * 检查位置是否为空
     * @param row 行
     * @param col 列
     * @return 是否为空
     */
    public boolean isEmpty(int row, int col) {
        return getCell(row, col) == Constants.EMPTY;
    }

    /**
     * 检查位置是否有效且为空
     * @param row 行
     * @param col 列
     * @return 是否有效且为空
     */
    public boolean isValidAndEmpty(int row, int col) {
        return row >= 0 && row < Constants.ROWS && col >= 0 && col < Constants.COLS && isEmpty(row, col);
    }

    /**
     * 检查方块是否可以放在指定位置
     * @param piece 方块
     * @param x 列偏移
     * @param y 行偏移
     * @return 是否可以放置
     */
    public boolean isValidPosition(Piece piece, int x, int y) {
        int[][] shape = piece.getShape();

        for (int row = 0; row < 4; row++) {
            for (int col = 0; col < 4; col++) {
                if (shape[row][col] == 1) {
                    int newRow = y + row;
                    int newCol = x + col;

                    // 检查边界
                    if (newCol < 0 || newCol >= Constants.COLS || newRow >= Constants.ROWS) {
                        return false;
                    }

                    // 检查是否与已存在的方块重叠
                    if (newRow >= 0 && !isEmpty(newRow, newCol)) {
                        return false;
                    }
                }
            }
        }

        return true;
    }

    /**
     * 将方块固定到游戏板
     * @param piece 方块
     */
    public void lockPiece(Piece piece) {
        int[][] shape = piece.getShape();
        int colorIndex = piece.getColorIndex();

        for (int row = 0; row < 4; row++) {
            for (int col = 0; col < 4; col++) {
                if (shape[row][col] == 1) {
                    int boardRow = piece.getY() + row;
                    int boardCol = piece.getX() + col;
                    setCell(boardRow, boardCol, colorIndex);
                }
            }
        }
    }

    /**
     * 检查并消除满行
     * @return 消除的行数
     */
    public int clearLines() {
        int linesCleared = 0;

        for (int row = Constants.ROWS - 1; row >= 0; row--) {
            if (isLineFull(row)) {
                removeLine(row);
                linesCleared++;
                row++;  // 重新检查当前行（因为下面的行上移了）
            }
        }

        return linesCleared;
    }

    /**
     * 检查指定行是否满
     * @param row 行号
     * @return 是否满
     */
    private boolean isLineFull(int row) {
        for (int col = 0; col < Constants.COLS; col++) {
            if (isEmpty(row, col)) {
                return false;
            }
        }
        return true;
    }

    /**
     * 移除指定行，下面的行上移
     * @param row 行号
     */
    private void removeLine(int row) {
        for (int r = row; r > 0; r--) {
            for (int col = 0; col < Constants.COLS; col++) {
                grid[r][col] = grid[r - 1][col];
            }
        }
        // 清空顶行
        for (int col = 0; col < Constants.COLS; col++) {
            grid[0][col] = Constants.EMPTY;
        }
    }

    /**
     * 检查游戏是否结束（顶部有方块）
     * @return 是否游戏结束
     */
    public boolean isGameOver() {
        // 检查第一行是否有方块
        for (int col = 0; col < Constants.COLS; col++) {
            if (!isEmpty(0, col)) {
                return true;
            }
        }
        return false;
    }

    /**
     * 获取网格数组引用（用于渲染）
     * @return 网格数组
     */
    public int[][] getGrid() {
        return grid;
    }

    /**
     * 打印游戏板（调试用）
     */
    public void print() {
        System.out.println("+------------------+");
        for (int row = 0; row < Constants.ROWS; row++) {
            StringBuilder sb = new StringBuilder("|");
            for (int col = 0; col < Constants.COLS; col++) {
                sb.append(grid[row][col] == Constants.EMPTY ? "  " : "[]");
            }
            sb.append("|");
            System.out.println(sb);
        }
        System.out.println("+------------------+");
    }
}

