package game;

import util.Constants;
import java.util.Random;

/**
 * 游戏状态枚举
 */
enum GameState {
    START,
    PLAYING,
    PAUSED,
    GAME_OVER
}

/**
 * 游戏控制器 - 核心游戏逻辑
 */
public class GameController {
    private Board board;
    private Piece currentPiece;
    private Piece nextPiece;
    private GameState state;

    private int score;
    private int level;
    private int linesCleared;

    private Random random;
    private long lastDropTime;
    private int currentSpeed;

    // 回调接口
    private Runnable onStateChanged;
    private Runnable onBoardChanged;

    public GameController() {
        board = new Board();
        random = new Random();
        state = GameState.START;
        score = 0;
        level = 1;
        linesCleared = 0;
        currentSpeed = Constants.LEVEL_SPEEDS[0];
        currentPiece = null;
        nextPiece = null;
    }

    /**
     * 开始新游戏
     */
    public void startGame() {
        board.clear();
        score = 0;
        level = 1;
        linesCleared = 0;
        currentSpeed = Constants.LEVEL_SPEEDS[0];
        state = GameState.PLAYING;

        nextPiece = generatePiece();
        spawnNewPiece();

        lastDropTime = System.currentTimeMillis();
        notifyStateChanged();
        notifyBoardChanged();
    }

    /**
     * 生成新方块
     */
    private Piece generatePiece() {
        Tetromino[] types = Tetromino.values();
        return new Piece(types[random.nextInt(types.length)]);
    }

    /**
     * 生成下一个方块
     */
    private void spawnNewPiece() {
        currentPiece = nextPiece;
        nextPiece = generatePiece();

        // 检查游戏结束
        if (!board.isValidPosition(currentPiece, currentPiece.getX(), currentPiece.getY())) {
            state = GameState.GAME_OVER;
            notifyStateChanged();
        }
    }

    /**
     * 更新游戏状态（自动下落）
     */
    public void update() {
        if (state != GameState.PLAYING) {
            return;
        }

        long currentTime = System.currentTimeMillis();
        if (currentTime - lastDropTime >= currentSpeed) {
            if (!moveDown()) {
                // 方块触底，固定并生成新的
                lockCurrentPiece();
            }
            lastDropTime = currentTime;
        }
    }

    /**
     * 方块下移
     * @return 是否移动成功
     */
    public boolean moveDown() {
        if (state != GameState.PLAYING || currentPiece == null) {
            return false;
        }

        if (board.isValidPosition(currentPiece, currentPiece.getX(), currentPiece.getY() + 1)) {
            currentPiece.moveDown();
            notifyBoardChanged();
            return true;
        }
        return false;
    }

    /**
     * 方块左移
     */
    public boolean moveLeft() {
        if (state != GameState.PLAYING || currentPiece == null) {
            return false;
        }

        if (board.isValidPosition(currentPiece, currentPiece.getX() - 1, currentPiece.getY())) {
            currentPiece.moveLeft();
            notifyBoardChanged();
            return true;
        }
        return false;
    }

    /**
     * 方块右移
     */
    public boolean moveRight() {
        if (state != GameState.PLAYING || currentPiece == null) {
            return false;
        }

        if (board.isValidPosition(currentPiece, currentPiece.getX() + 1, currentPiece.getY())) {
            currentPiece.moveRight();
            notifyBoardChanged();
            return true;
        }
        return false;
    }

    /**
     * 方块旋转
     */
    public boolean rotate() {
        if (state != GameState.PLAYING || currentPiece == null) {
            return false;
        }

        Piece rotated = currentPiece.copy();
        rotated.rotate();

        // 尝试墙踢
        int[][] kicks = {{0, 0}, {-1, 0}, {1, 0}, {0, -1}, {-2, 0}, {2, 0}};

        for (int[] kick : kicks) {
            int newX = currentPiece.getX() + kick[0];
            int newY = currentPiece.getY() + kick[1];

            if (board.isValidPosition(rotated, newX, newY)) {
                currentPiece.setPosition(newX, newY);
                currentPiece.rotate();
                notifyBoardChanged();
                return true;
            }
        }

        return false;
    }

    /**
     * 软降 (加速下落)
     */
    public void softDrop() {
        if (moveDown()) {
            score += Constants.SOFT_DROP_SCORE;
            notifyStateChanged();
        }
    }

    /**
     * 硬降 (直接落到底)
     */
    public void hardDrop() {
        if (state != GameState.PLAYING || currentPiece == null) {
            return;
        }

        int dropDistance = 0;
        while (board.isValidPosition(currentPiece, currentPiece.getX(), currentPiece.getY() + 1)) {
            currentPiece.moveDown();
            dropDistance++;
        }

        score += dropDistance * Constants.HARD_DROP_SCORE;
        lockCurrentPiece();
    }

    /**
     * 固定当前方块到游戏板
     */
    private void lockCurrentPiece() {
        if (currentPiece == null) {
            return;
        }

        board.lockPiece(currentPiece);
        currentPiece = null;

        // 消除行
        int lines = board.clearLines();
        if (lines > 0) {
            linesCleared += lines;
            score += Constants.LINE_SCORES[lines] * level;

            // 检查升级
            int newLevel = (linesCleared / Constants.LINES_PER_LEVEL) + 1;
            if (newLevel > level && newLevel <= 10) {
                level = newLevel;
                currentSpeed = Constants.LEVEL_SPEEDS[level - 1];
            }
        }

        notifyStateChanged();
        notifyBoardChanged();

        // 生成下一个方块
        spawnNewPiece();
    }

    /**
     * 切换暂停状态
     */
    public void togglePause() {
        if (state == GameState.PLAYING) {
            state = GameState.PAUSED;
        } else if (state == GameState.PAUSED) {
            state = GameState.PLAYING;
            lastDropTime = System.currentTimeMillis();
        }
        notifyStateChanged();
    }

    /**
     * 获取游戏状态
     */
    public GameState getState() {
        return state;
    }

    /**
     * 获取游戏板
     */
    public Board getBoard() {
        return board;
    }

    /**
     * 获取当前方块
     */
    public Piece getCurrentPiece() {
        return currentPiece;
    }

    /**
     * 获取下一个方块
     */
    public Piece getNextPiece() {
        return nextPiece;
    }

    /**
     * 获取分数
     */
    public int getScore() {
        return score;
    }

    /**
     * 获取等级
     */
    public int getLevel() {
        return level;
    }

    /**
     * 获取消除行数
     */
    public int getLinesCleared() {
        return linesCleared;
    }

    /**
     * 设置状态改变回调
     */
    public void setOnStateChanged(Runnable callback) {
        this.onStateChanged = callback;
    }

    /**
     * 设置游戏板改变回调
     */
    public void setOnBoardChanged(Runnable callback) {
        this.onBoardChanged = callback;
    }

    private void notifyStateChanged() {
        if (onStateChanged != null) {
            onStateChanged.run();
        }
    }

    private void notifyBoardChanged() {
        if (onBoardChanged != null) {
            onBoardChanged.run();
        }
    }
}

