package ui;

import game.GameController;
import game.GameState;
import game.Piece;
import util.Constants;

import javax.swing.*;
import java.awt.*;

/**
 * 游戏面板 - 负责渲染游戏画面
 */
public class GamePanel extends JPanel {
    private GameController controller;
    private Image bufferImage;
    private Graphics2D bufferGraphics;

    public GamePanel(GameController controller) {
        this.controller = controller;
        setPreferredSize(new Dimension(Constants.BOARD_WIDTH, Constants.BOARD_HEIGHT));
        setBackground(Constants.BOARD_BG);
        setBorder(BorderFactory.createLineBorder(Constants.BORDER_COLOR, 2));
    }

    @Override
    protected void paintComponent(Graphics g) {
        super.paintComponent(g);

        Graphics2D g2d = (Graphics2D) g;
        g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        // 绘制背景
        g2d.setColor(Constants.BOARD_BG);
        g2d.fillRect(0, 0, getWidth(), getHeight());

        // 绘制网格线
        drawGrid(g2d);

        // 绘制已固定的方块
        drawBoard(g2d);

        // 绘制当前方块和下一个方块
        drawCurrentPiece(g2d);

        // 绘制游戏状态覆盖层
        drawOverlay(g2d);
    }

    /**
     * 绘制网格线
     */
    private void drawGrid(Graphics2D g2d) {
        g2d.setColor(Constants.GRID_COLOR);
        g2d.setStroke(new BasicStroke(1));

        // 垂直线
        for (int x = 0; x <= Constants.COLS; x++) {
            int px = x * Constants.CELL_SIZE;
            g2d.drawLine(px, 0, px, Constants.BOARD_HEIGHT);
        }

        // 水平线
        for (int y = 0; y <= Constants.ROWS; y++) {
            int py = y * Constants.CELL_SIZE;
            g2d.drawLine(0, py, Constants.BOARD_WIDTH, py);
        }
    }

    /**
     * 绘制游戏板上的已固定方块
     */
    private void drawBoard(Graphics2D g2d) {
        int[][] grid = controller.getBoard().getGrid();

        for (int row = 0; row < Constants.ROWS; row++) {
            for (int col = 0; col < Constants.COLS; col++) {
                int colorIndex = grid[row][col];
                if (colorIndex != Constants.EMPTY) {
                    int x = col * Constants.CELL_SIZE;
                    int y = row * Constants.CELL_SIZE;
                    drawBlock(g2d, x, y, colorIndex);
                }
            }
        }
    }

    /**
     * 绘制当前下落的方块
     */
    private void drawCurrentPiece(Graphics2D g2d) {
        Piece piece = controller.getCurrentPiece();
        if (piece == null) {
            return;
        }

        int colorIndex = piece.getColorIndex();
        int[][] shape = piece.getShape();

        // 绘制方块
        for (int row = 0; row < 4; row++) {
            for (int col = 0; col < 4; col++) {
                if (shape[row][col] == 1) {
                    int x = (piece.getX() + col) * Constants.CELL_SIZE;
                    int y = (piece.getY() + row) * Constants.CELL_SIZE;
                    drawBlock(g2d, x, y, colorIndex);
                }
            }
        }
    }

    /**
     * 绘制单个方块（带3D效果）
     */
    private void drawBlock(Graphics2D g2d, int x, int y, int colorIndex) {
        Color blockColor = Constants.TETROMINO_COLORS[colorIndex];
        int size = Constants.CELL_SIZE;
        int inset = 2;

        // 主体
        g2d.setColor(blockColor);
        g2d.fillRect(x + inset, y + inset, size - inset * 2, size - inset * 2);

        // 高光边框 (左上)
        g2d.setColor(Constants.BLOCK_HIGHLIGHT);
        g2d.fillRect(x + inset, y + inset, size - inset * 2, 3);
        g2d.fillRect(x + inset, y + inset, 3, size - inset * 2);

        // 阴影边框 (右下)
        g2d.setColor(new Color(0x20000000, true));
        g2d.fillRect(x + size - inset - 3, y + inset, 3, size - inset * 2);
        g2d.fillRect(x + inset, y + size - inset - 3, size - inset * 2, 3);

        // 方块边框
        g2d.setColor(Constants.BLOCK_BORDER);
        g2d.drawRect(x + inset, y + inset, size - inset * 2 - 1, size - inset * 2 - 1);
    }

    /**
     * 绘制覆盖层（开始/暂停/结束）
     */
    private void drawOverlay(Graphics2D g2d) {
        GameState state = controller.getState();

        switch (state) {
            case START -> drawStartOverlay(g2d);
            case PAUSED -> drawPausedOverlay(g2d);
            case GAME_OVER -> drawGameOverOverlay(g2d);
            default -> {}
        }
    }

    /**
     * 绘制开始界面
     */
    private void drawStartOverlay(Graphics2D g2d) {
        // 半透明背景
        g2d.setColor(new Color(0x801a1a2e));
        g2d.fillRect(0, 0, Constants.BOARD_WIDTH, Constants.BOARD_HEIGHT);

        // 标题
        g2d.setColor(Constants.ACCENT_COLOR);
        g2d.setFont(new Font("Arial", Font.BOLD, 24));
        String title = "TETRIS";
        int titleWidth = g2d.getFontMetrics().stringWidth(title);
        g2d.drawString(title, (Constants.BOARD_WIDTH - titleWidth) / 2, Constants.BOARD_HEIGHT / 2 - 40);

        // 提示
        g2d.setColor(Color.WHITE);
