package ui;

import game.GameController;
import game.Piece;
import util.Constants;

import javax.swing.*;
import java.awt.*;

/**
 * 侧边面板 - 显示下一个方块、分数、等级等信息
 */
public class SidePanel extends JPanel {
    private GameController controller;

    private JLabel scoreLabel;
    private JLabel levelLabel;
    private JLabel linesLabel;
    private PreviewPanel previewPanel;

    public SidePanel(GameController controller) {
        this.controller = controller;
        setPreferredSize(new Dimension(Constants.SIDE_PANEL_WIDTH, Constants.BOARD_HEIGHT));
        setBackground(Constants.BG_COLOR);
        setLayout(new BorderLayout(10, 10));
        setBorder(BorderFactory.createEmptyBorder(15, 15, 15, 15));

        initComponents();
    }

    private void initComponents() {
        // 标题
        JLabel titleLabel = new JLabel("TETRIS", JLabel.CENTER);
        titleLabel.setFont(Constants.TITLE_FONT);
        titleLabel.setForeground(Constants.ACCENT_COLOR);
        add(titleLabel, BorderLayout.NORTH);

        // 中间区域
        JPanel centerPanel = new JPanel();
        centerPanel.setLayout(new BoxLayout(centerPanel, BoxLayout.Y_AXIS));
        centerPanel.setBackground(Constants.BG_COLOR);

        // 下一个方块预览
        JPanel nextPanel = new JPanel();
        nextPanel.setLayout(new BoxLayout(nextPanel, BoxLayout.Y_AXIS));
        nextPanel.setBackground(Constants.BG_COLOR);
        nextPanel.setAlignmentX(Component.CENTER_ALIGNMENT);

        JLabel nextTitle = new JLabel("NEXT", JLabel.CENTER);
        nextTitle.setFont(Constants.LABEL_FONT);
        nextTitle.setForeground(Constants.TEXT_COLOR);
        nextTitle.setAlignmentX(Component.CENTER_ALIGNMENT);
        nextPanel.add(nextTitle);

        previewPanel = new PreviewPanel();
        previewPanel.setMaximumSize(new Dimension(120, 120));
        previewPanel.setAlignmentX(Component.CENTER_ALIGNMENT);
        nextPanel.add(Box.createVerticalStrut(10));
        nextPanel.add(previewPanel);

        centerPanel.add(nextPanel);
        centerPanel.add(Box.createVerticalStrut(30));

        // 分数面板
        JPanel scorePanel = createInfoPanel("SCORE", scoreLabel = new JLabel("0"));
        centerPanel.add(scorePanel);
        centerPanel.add(Box.createVerticalStrut(15));

        // 等级面板
        JPanel levelPanel = createInfoPanel("LEVEL", levelLabel = new JLabel("1"));
        centerPanel.add(levelPanel);
        centerPanel.add(Box.createVerticalStrut(15));

        // 消除行数面板
        JPanel linesPanel = createInfoPanel("LINES", linesLabel = new JLabel("0"));
        centerPanel.add(linesPanel);

        add(centerPanel, BorderLayout.CENTER);

        // 控制说明
        JPanel controlsPanel = new JPanel();
        controlsPanel.setLayout(new BoxLayout(controlsPanel, BoxLayout.Y_AXIS));
        controlsPanel.setBackground(Constants.BG_COLOR);

        JLabel controlsTitle = new JLabel("CONTROLS", JLabel.CENTER);
        controlsTitle.setFont(Constants.LABEL_FONT);
        controlsTitle.setForeground(Constants.ACCENT_COLOR);
        controlsTitle.setAlignmentX(Component.CENTER_ALIGNMENT);
        controlsPanel.add(controlsTitle);
        controlsPanel.add(Box.createVerticalStrut(10));

        String[] controls = {
            "← → : 移动",
            "↑    : 旋转",
            "↓    : 软降",
            "空格 : 硬降",
            "P    : 暂停"
        };

        for (String control : controls) {
            JLabel label = new JLabel(control, JLabel.CENTER);
            label.setFont(Constants.CONTROL_FONT);
            label.setForeground(Constants.TEXT_COLOR);
            label.setAlignmentX(Component.CENTER_ALIGNMENT);
            controlsPanel.add(label);
        }

        add(controlsPanel, BorderLayout.SOUTH);
    }

    private JPanel createInfoPanel(String title, JLabel valueLabel) {
        JPanel panel = new JPanel();
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
