package ui;

import game.GameController;
import game.GameState;

import javax.swing.*;
import java.awt.*;
import java.awt.event.KeyAdapter;
import java.awt.event.KeyEvent;

/**
 * 主窗口 - 游戏主界面
 */
public class GameFrame extends JFrame {
    private GameController controller;
    private GamePanel gamePanel;
    private SidePanel sidePanel;
    private Timer gameTimer;

    public GameFrame() {
        controller = new GameController();

        setTitle("Tetris - 俄罗斯方块");
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setResizable(false);
        setBackground(Constants.BG_COLOR);

        // 设置内容面板
        JPanel contentPanel = new JPanel();
        contentPanel.setLayout(new BoxLayout(contentPanel, BoxLayout.X_AXIS));
        contentPanel.setBackground(Constants.BG_COLOR);
        contentPanel.setBorder(BorderFactory.createEmptyBorder(20, 20, 20, 20));

        // 游戏面板
        gamePanel = new GamePanel(controller);
        contentPanel.add(gamePanel);

        // 间距
        contentPanel.add(Box.createHorizontalStrut(20));

        // 侧边面板
        sidePanel = new SidePanel(controller);
        contentPanel.add(sidePanel);

        add(contentPanel);
        pack();

        // 居中显示
        setLocationRelativeTo(null);

        // 设置键盘监听
        setupKeyListener();

        // 设置回调
        controller.setOnStateChanged(this::onStateChanged);
        controller.setOnBoardChanged(this::onBoardChanged);

        // 游戏循环定时器
        gameTimer = new Timer(16, e -> {  // 约60fps
            controller.update();
            gamePanel.repaint();
        });
        gameTimer.start();
    }

    private void setupKeyListener() {
        addKeyListener(new KeyAdapter() {
            @Override
            public void keyPressed(KeyEvent e) {
                handleKeyPress(e);
            }
        });
        setFocusable(true);
    }

    private void handleKeyPress(KeyEvent e) {
        switch (controller.getState()) {
            case START -> {
                controller.startGame();
            }
            case PLAYING -> {
                switch (e.getKeyCode()) {
                    case KeyEvent.VK_LEFT -> controller.moveLeft();
                    case KeyEvent.VK_RIGHT -> controller.moveRight();
                    case KeyEvent.VK_UP -> controller.rotate();
                    case KeyEvent.VK_DOWN -> controller.softDrop();
                    case KeyEvent.VK_SPACE -> controller.hardDrop();
                    case KeyEvent.VK_P -> controller.togglePause();
                }
            }
            case PAUSED -> {
                if (e.getKeyCode() == KeyEvent.VK_P) {
                    controller.togglePause();
                }
            }
            case GAME_OVER -> {
                if (e.getKeyCode() == KeyEvent.VK_R) {
                    controller.startGame();
                }
            }
        }

        gamePanel.repaint();
    }

    private void onStateChanged() {
        sidePanel.update();
    }

    private void onBoardChanged() {
        gamePanel.repaint();
        sidePanel.update();
    }
}

