package game;

import util.Constants;

/**
 * 方块对象，表示当前下落的方块
 */
public class Piece {
    private Tetromino type;
    private int x;          // 列位置 (0-based)
    private int y;          // 行位置 (0-based)
    private int rotation;   // 旋转状态 (0-3)

    public Piece(Tetromino type) {
        this.type = type;
        this.x = Constants.COLS / 2 - 2;  // 居中放置
        this.y = 0;
        this.rotation = 0;
    }

    public Piece(Piece other) {
        this.type = other.type;
        this.x = other.x;
        this.y = other.y;
        this.rotation = other.rotation;
    }

    /**
     * 获取当前形状矩阵
     */
    public int[][] getShape() {
        return type.getShape(rotation);
    }

    /**
     * 获取颜色索引
     */
    public int getColorIndex() {
        return type.getColorIndex();
    }

    /**
     * 左移
     */
    public void moveLeft() {
        x--;
    }

    /**
     * 右移
     */
    public void moveRight() {
        x++;
    }

    /**
     * 下移
     */
    public void moveDown() {
        y++;
    }

    /**
     * 上移 (用于硬降后检查)
     */
    public void moveUp() {
        y--;
    }

    /**
     * 顺时针旋转90度
     */
    public void rotate() {
        rotation = (rotation + 1) % 4;
    }

    /**
     * 逆时针旋转
     */
    public void rotateCounterClockwise() {
        rotation = (rotation + 3) % 4;
    }

    /**
     * 获取X坐标
     */
    public int getX() {
        return x;
    }

    /**
     * 获取Y坐标
     */
    public int getY() {
        return y;
    }

    /**
     * 获取旋转状态
     */
    public int getRotation() {
        return rotation;
    }

    /**
     * 获取方块类型
     */
    public Tetromino getType() {
        return type;
    }

    /**
     * 设置位置
     */
    public void setPosition(int x, int y) {
        this.x = x;
        this.y = y;
    }

    /**
     * 设置旋转状态
     */
    public void setRotation(int rotation) {
        this.rotation = rotation % 4;
    }

    /**
     * 创建副本
     */
    public Piece copy() {
        return new Piece(this);
    }

    /**
     * 获取方块占据的单元格坐标
     * @return 二维数组，每个元素是 {row, col}
     */
    public int[][] getCells() {
        int[][] shape = getShape();
        int[][] cells = new int[4][2];
        int index = 0;

        for (int row = 0; row < 4; row++) {
            for (int col = 0; col < 4; col++) {
                if (shape[row][col] == 1) {
                    cells[index][0] = y + row;
                    cells[index][1] = x + col;
                    index++;
                }
            }
        }

        return cells;
    }
}

