        // 测试移动
        piece.moveLeft();
        System.out.println("After moveLeft: x=" + piece.getX());

        piece.moveRight();
        piece.moveRight();
        System.out.println("After 2x moveRight: x=" + piece.getX());

        // 测试旋转
        piece.rotate();
        System.out.println("After rotate: rotation=" + piece.getRotation());

