    private JPanel createInfoPanel(String title, JLabel valueLabel) {
        JPanel panel = new JPanel();
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setBackground(new Color(0xFF252540));
        panel.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
        panel.setAlignmentX(Component.CENTER_ALIGNMENT);

        JLabel titleLabel = new JLabel(title, JLabel.CENTER);
        titleLabel.setFont(Constants.LABEL_FONT);
        titleLabel.setForeground(Constants.TEXT_COLOR);
        titleLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
        panel.add(titleLabel);

        valueLabel.setFont(Constants.VALUE_FONT);
        valueLabel.setForeground(Constants.ACCENT_COLOR);
        valueLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
        panel.add(valueLabel);

        return panel;
    }

    /**
     * 更新显示
     */
    public void update() {
        scoreLabel.setText(String.valueOf(controller.getScore()));
        levelLabel.setText(String.valueOf(controller.getLevel()));
        linesLabel.setText(String.valueOf(controller.getLinesCleared()));
        previewPanel.repaint();
    }

    /**
     * 预览面板 - 显示下一个方块
     */
    private class PreviewPanel extends JPanel {
        public PreviewPanel() {
            setPreferredSize(new Dimension(120, 120));
            setBackground(Constants.BOARD_BG);
            setBorder(BorderFactory.createLineBorder(Constants.BORDER_COLOR));
        }

        @Override
        protected void paintComponent(Graphics g) {
            super.paintComponent(g);
            Graphics2D g2d = (Graphics2D) g;
            g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

            Piece piece = controller.getNextPiece();
            if (piece == null) {
                return;
            }

            int[][] shape = piece.getShape();
            int colorIndex = piece.getColorIndex();

            // 计算方块占据的区域
            int minX = 4, maxX = 0, minY = 4, maxY = 0;
            for (int row = 0; row < 4; row++) {
                for (int col = 0; col < 4; col++) {
                    if (shape[row][col] == 1) {
                        minX = Math.min(minX, col);
                        maxX = Math.max(maxX, col);
                        minY = Math.min(minY, row);
                        maxY = Math.max(maxY, row);
                    }
                }
            }

            int blockWidth = maxX - minX + 1;
            int blockHeight = maxY - minY + 1;

            // 计算居中位置
            int cellSize = 25;
            int totalWidth = blockWidth * cellSize;
            int totalHeight = blockHeight * cellSize;
            int startX = (getWidth() - totalWidth) / 2 - minX * cellSize;
            int startY = (getHeight() - totalHeight) / 2 - minY * cellSize;

            for (int row = 0; row < 4; row++) {
                for (int col = 0; col < 4; col++) {
                    if (shape[row][col] == 1) {
                        int x = startX + col * cellSize;
                        int y = startY + row * cellSize;
                        drawBlock(g2d, x, y, colorIndex);
                    }
                }
            }
        }

        private void drawBlock(Graphics2D g2d, int x, int y, int colorIndex) {
            Color blockColor = Constants.TETROMINO_COLORS[colorIndex];
            int size = 25;
            int inset = 1;

            g2d.setColor(blockColor);
            g2d.fillRect(x + inset, y + inset, size - inset * 2, size - inset * 2);

            g2d.setColor(Constants.BLOCK_BORDER);
            g2d.drawRect(x + inset, y + inset, size - inset * 2 - 1, size - inset * 2 - 1);
        }
    }
}

